function coMenu() {
  const C = S.coach, D = coachDigest();
  coAnswer(`<div class="co-lab">Ask</div>${coChips(coAskChips(D), null, true)}
    <div class="co-lab">Plan</div>${coChips([...(C.plan ? [['see', 'See my plan']] : []), ['new', C.plan ? 'New plan' : 'Build my plan'], ['import', 'Bring in my own plan'], ['answers', 'Change my answers'], ['test', 'Fitting test'], ['settings', 'Coach settings']], null, true)}
    ${coFormHtml()}`);
  $('#coAns', CO.bg).querySelectorAll('[data-cov]').forEach(b => b.onclick = () => coMenuPick(b.dataset.cov, b.textContent));
  coFormWire();
}
function coMenuPick(v, label) {
  const C = S.coach;
  if (CO) CO.lastText = null;
  coBubble('me', esc(label));
  if (v === 'menu') return coMenu();
  if (v === 'settings') { openCoachSettings(); return coMenu(); }
  if (v === 'see') return coPreview(C.plan, true);
  if (v === 'new') { C.answers.planMode = 'build'; save(); return coNext(); }   // asks any plan question skipped earlier, then builds
  if (v === 'import') return coImport();
  if (v === 'answers') return coAnswers();
  if (v === 'test') { closeAllModals(); return openFitTest('home'); }
  if (v === 'go') { closeAllModals(); return go('workout'); }
  if (v === 'checkin') { closeAllModals(); return openCheckin(today()); }
  if (v.startsWith('ramp:')) { const [, k, kg] = v.split(':'); return openRamp(k, +kg || 0); }
  if (v.startsWith('plates:')) { const kg = +v.split(':')[1] || 0; if (/Open the plate loader/.test(label)) return openPlates(kg); return coAnswerTopic('plates', String(nice(dw(kg)))); }
  if (v.startsWith('sugg:')) { const [, kind, ...rest] = v.split(':'); return coOfferChange(kind, rest.join(':') || undefined); }
  if (v.startsWith('fitres:')) return openFitResults(v.slice(7));
  if (v === 'cardio') { closeAllModals(); return openCardioSetup(); }
  if (v === 'mobility') { closeAllModals(); const r = BUILTIN_ROUTINES[0]; return r && openMobility(r.id, today()); }
  if (v.startsWith('note:')) { const t = v.slice(5), M = coachMem(); M.notes = [...M.notes, `Doesn't like ${t}`].slice(-20); save(); coBubble('coach', 'Saved to your notes.'); return coMenu(); }
  if (v.startsWith('apply:')) { const [, kind, arg] = v.split(':'); return coApplyChange(kind, arg); }
  if (v === 'undo') return coUndoChange();
  if (v.startsWith('easy:')) {
    const j = v.split(':')[1], A = coachMem().answers;
    A.easy = [...new Set([...(A.easy || []), j])]; save();
    coBubble('coach', `Noted — going easy on ${esc((MOB_JOINTS.find(x => x[0] === j) || [j, j])[1].toLowerCase())}.${C.plan ? ' Want a new plan that works around it?' : ''}`);
    return coFollow(C.plan ? [['new', 'Rebuild my plan']] : []);
  }
  const [topic, arg] = v.split(':');
  coAnswerTopic(topic, arg);
}
/* The next unanswered step, or the fitting-test invite once they're all in. */
function coNext() {
  const A = S.coach.answers;
  const st = COACH_STEPS.find(s => (!s.show || s.show(A)) && !(S.coach.asked || []).includes(s.id));
  if (!st) {
    S.coach.setupDone = true; S.coach.setupAt = S.coach.setupAt || today(); save();
    if (A.planMode === 'import') { coBubble('coach', 'Good — let\'s bring your plan in. Any format works; an AI turns it into Ironlog\'s.'); return coImport(); }
    if (A.planMode === 'none') { coBubble('coach', coPick(['No plan — just log. I\'m here when you want one, and you can ask me about your training any time.', 'Fair enough — log as you go. Ask me anything about your training, or tap Build my plan whenever you want one.'])); return coMenu(); }
    if (A.planMode === 'keep') {
      const p = coExistingProg();
      if (p) Object.assign(S.coach, { planProg: p, planName: programName(p), planAt: S.coach.planAt || today() });
      save();
      coBubble('coach', p ? `Good — I'll work with ${esc(programName(p))}. Ask me about any session or lift in it.` : 'That plan has no sessions left — want a new one?');
      return coMenu();
    }
    return coInvite();
  }
  coAsk(st, () => { (S.coach.asked = S.coach.asked || []).push(st.id); save(); coNext(); });
}
/* Ask one step; done() runs once it's answered. */
function coAsk(st, done) {
  const A = S.coach.answers;
  coBubble('coach', esc(st.ask(A)));
  const finish = text => { if (st.apply) st.apply(A[st.id]); coBubble('me', esc(text)); save(); done(); };
  const wire = fn => $('#coAns', CO.bg).querySelectorAll('[data-cov]').forEach(b => b.onclick = () => fn(b.dataset.cov, b));
  if (st.kind === 'single') {
    coAnswer(coChips(st.opts(A), A[st.id] != null ? [String(A[st.id])] : null));
    wire(v => { A[st.id] = /^\d+$/.test(v) ? +v : v; finish(coachAnswerText(st, A)); });
  } else if (st.kind === 'multi') {
    const sel = new Set((A[st.id] || []).map(String));
    const draw = () => {
      coAnswer(`${coChips(st.opts(A), [...sel])}<button class="btn primary sm wide" id="coOk" style="margin-top:8px">${sel.size ? 'Done' : esc(st.none || 'Done')}</button>`);
      wire((v, b) => { sel.has(v) ? sel.delete(v) : sel.add(v); b.classList.toggle('on'); b.setAttribute('aria-pressed', sel.has(v)); $('#coOk', CO.bg).textContent = sel.size ? 'Done' : (st.none || 'Done'); });
      $('#coOk', CO.bg).onclick = () => { A[st.id] = [...sel]; finish(coachAnswerText(st, A)); };
    };
    draw();
  } else if (st.kind === 'date') {
    const nextMeet = (S.meets || []).filter(m => m.date > today()).sort((a, b) => a.date < b.date ? -1 : 1)[0];
    const cur = A.eventDate && A.eventDate !== 'none' ? A.eventDate : nextMeet ? nextMeet.date : '';
    coAnswer(`<div class="row" style="gap:8px;align-items:flex-end"><div class="field grow" style="margin:0"><label for="coDate">Event date</label><input type="date" id="coDate" min="${today()}" value="${esc(cur)}"></div>
      <button class="btn primary sm" id="coDateOk">Use date</button></div>${coChips([['none', 'No event yet']])}`);
    $('#coDateOk', CO.bg).onclick = () => { const v = $('#coDate', CO.bg).value; if (!v) return toast('Pick a date, or tap No event yet'); A.eventDate = v; finish(coachAnswerText(st, A)); };
    wire(() => { A.eventDate = 'none'; finish('No event yet'); });
  } else if (st.kind === 'dob') {
    coAnswer(`<div class="row" style="gap:8px;align-items:flex-end"><div class="field grow" style="margin:0"><label for="coDob">Date of birth</label><input type="date" id="coDob" max="${today()}" value="${esc(A.dob && A.dob !== 'skip' ? A.dob : '')}"></div>
      <button class="btn primary sm" id="coDobOk">OK</button></div>${coChips([['skip', 'Rather not say']])}`);
    $('#coDobOk', CO.bg).onclick = () => {
      const v = $('#coDob', CO.bg).value, a = v ? ageFrom(v) : null;
      if (!v || !(a >= 10 && a <= 100)) return toast('Pick your date of birth, or tap Rather not say');
      A.dob = v; finish(coachAnswerText(st, A));
    };
    wire(() => { A.dob = 'skip'; finish('Rather not say'); });
  } else if (st.kind === 'number') {
    coAnswer(`<div class="row" style="gap:8px;align-items:flex-end"><div class="field grow" style="margin:0"><label for="coNum">${esc(st.label || 'Bodyweight')} (${esc(st.unit())})</label><input type="number" inputmode="decimal" step="0.1" min="0" id="coNum" value="${A[st.id] > 0 ? nice(dw(A[st.id])) : ''}"></div>
      <button class="btn primary sm" id="coNumOk">OK</button></div>${coChips([['skip', 'Skip for now']])}`);
    $('#coNumOk', CO.bg).onclick = () => {
      const kg = toKg(parseFloat(String($('#coNum', CO.bg).value).replace(',', '.')) || 0);
      if (!(kg >= 25 && kg <= 350)) return toast(`Enter ${st.label ? st.label.toLowerCase() : 'your bodyweight'}, or tap Skip for now`);
      A[st.id] = kg; finish(coachAnswerText(st, A));
    };
    wire(() => { A[st.id] = 0; finish('Skip for now'); });
  } else if (st.kind === 'days') {
    const sel = new Set(A.days || []);
    const line = () => sel.size ? `${sel.size} day${sel.size === 1 ? '' : 's'} → <b>${esc(coachSplitName(sel.size))}</b>` : 'Tap your training days.';
    coAnswer(`${coChips(COACH_WD.map(w => [w[0], w[1]]), [...sel])}<div class="sub" id="coSplit" style="margin:8px 0" aria-live="polite">${line()}</div><button class="btn primary sm wide" id="coOk">Done</button>`);
    wire((v, b) => {
      if (!sel.has(v) && sel.size >= 6) return toast('Pick at least one rest day');
      sel.has(v) ? sel.delete(v) : sel.add(v);
      b.classList.toggle('on', sel.has(v)); b.setAttribute('aria-pressed', sel.has(v));
      $('#coSplit', CO.bg).innerHTML = line();
    });
    $('#coOk', CO.bg).onclick = () => { if (!sel.size) return toast('Tap at least one day'); A.days = [...sel]; finish(coachAnswerText(st, A)); };
  } else if (st.kind === 'dayPlace') {
    const dp = { ...(A.dayPlace || {}) };
    coAnswer(`${coachDays(A).map(d => `<div class="row between" style="margin:4px 0"><span>${COACH_WD.find(w => w[0] === d)[1]}</span>
      <div class="seg" data-codp="${d}"><button data-v="gym" class="${dp[d] !== 'home' ? 'on' : ''}">Gym</button><button data-v="home" class="${dp[d] === 'home' ? 'on' : ''}">Home</button></div></div>`).join('')}
      <button class="btn primary sm wide" id="coOk" style="margin-top:8px">Done</button>`);
    $('#coAns', CO.bg).querySelectorAll('[data-codp]').forEach(sg => sg.querySelectorAll('button').forEach(b => b.onclick = () => {
      dp[sg.dataset.codp] = b.dataset.v; sg.querySelectorAll('button').forEach(x => x.classList.toggle('on', x === b));
    }));
    $('#coOk', CO.bg).onclick = () => { A.dayPlace = dp; finish(coachAnswerText(st, A)); };
  } else if (st.kind === 'place') coAskPlace(st, A, finish);
}
/* Kit in two taps (spec §1a): an existing place, a standard gym, or a few chips. */
function coAskPlace(st, A, finish) {
  const gym = st.which === 'gym';
  const make = (name, kit, extras) => {
    const p = { id: uid(), name, kit: ['bodyweight', ...kit].filter((v, i, a) => a.indexOf(v) === i), ...(extras ? { extras } : {}), mt: Date.now() };
    S.settings.places = [...places(), p];
    return p.id;
  };
  const chipsKit = () => {
    const sel = new Set();
    coAnswer(`${coChips(COACH_HOME_KIT.map(k => [k[0], k[1]]))}<button class="btn primary sm wide" id="coOk" style="margin-top:8px">Nothing — bodyweight</button>`);
    $('#coAns', CO.bg).querySelectorAll('[data-cov]').forEach(b => b.onclick = () => {
      const v = b.dataset.cov; sel.has(v) ? sel.delete(v) : sel.add(v);
      b.classList.toggle('on', sel.has(v)); b.setAttribute('aria-pressed', sel.has(v));
      $('#coOk', CO.bg).textContent = sel.size ? 'Done' : 'Nothing — bodyweight';
    });
    $('#coOk', CO.bg).onclick = () => {
      const picked = COACH_HOME_KIT.filter(k => sel.has(k[0]));
      A[st.id] = make(gym ? 'Gym' : 'Home', picked.flatMap(k => k[2]), picked.flatMap(k => k[3]));
      finish(picked.length ? picked.map(k => k[1]).join(', ') : 'Nothing — bodyweight');
    };
  };
  const fresh = () => {
    if (!gym) return chipsKit();
    coAnswer(coChips([['std', 'Yes, standard'], ['sm', 'Strongman gym'], ['small', 'Smaller than that']]));
    $('#coAns', CO.bg).querySelectorAll('[data-cov]').forEach(b => b.onclick = () => {
      const v = b.dataset.cov;
      if (v === 'small') { coBubble('me', 'Smaller than that'); coBubble('coach', 'What has it got?'); return chipsKit(); }
      const preset = PLACE_PRESETS.find(p => p.name === (v === 'sm' ? 'Strongman gym' : 'Commercial gym'));
      const kit = preset.kit || (catalogue().V.equipment || []).map(e => e.id || e);
      A[st.id] = make(v === 'sm' ? 'Strongman gym' : 'Gym', kit, null);
      finish(b.textContent);
    });
  };
  if (!places().length) return fresh();
  coAnswer(coChips([...places().map(p => [p.id, p.name]), ['new', gym ? 'Another gym' : 'Set up home']], A[st.id] ? [A[st.id]] : null));
  $('#coAns', CO.bg).querySelectorAll('[data-cov]').forEach(b => b.onclick = () => {
    const v = b.dataset.cov;
    if (v !== 'new') { A[st.id] = v; return finish(b.textContent); }
    coBubble('me', esc(b.textContent));
    coBubble('coach', esc(gym ? 'Is it a standard gym — racks, barbells, dumbbells, cables and machines?' : 'What have you got at home?'));
    fresh();
  });
}
/* An imported plan becomes the coach's current plan. */
function coImport() {
  openPlanImport((P, n) => {
    const C = coachMem();
    Object.assign(C, { plan: null, planProg: P.id, planName: P.name, planAt: today(), draft: null });
    save();
    openCoach();
    coBubble('coach', `${esc(P.name)} is on your calendar — ${n} session${n === 1 ? '' : 's'}. I'll review it with you as you train.`);
  }, [coachMem().planProg]);
}
/* Spec §1b: offer the fitting test before building, or use a recent one. */
function coInvite() {
  /* Someone set up before these were asked still gets them, once. */
  const miss = COACH_STEPS.find(s => ['sex', 'dob', 'bw'].includes(s.id) && s.show(S.coach.answers) && !(S.coach.asked || []).includes(s.id));
  if (miss) return coAsk(miss, () => { (S.coach.asked = S.coach.asked || []).push(miss.id); save(); coInvite(); });
  const t = coachRecentTest();
  if (t) { coBubble('coach', `Using your fitting test from ${esc(fmtDate(t.date))} — it shapes the plan.`); return coBuildAndShow(t); }
  coBubble('coach', 'Want to do the fitting test first? 15 minutes at home now, the gym hour on your first gym day. It finds your weak spots and starting weights, and the plan uses both.');
  coAnswer(coChips([['home', 'Home screen now'], ['full', 'Full test at the gym'], ['skip', 'Skip — build from my answers']]));
  $('#coAns', CO.bg).querySelectorAll('[data-cov]').forEach(b => b.onclick = () => {
    const v = b.dataset.cov;
    coBubble('me', esc(b.textContent));
    if (v === 'home') { S.coach.awaitTest = true; save(); closeAllModals(); return openFitTest('home'); }
    if (v === 'full') { S.coach.awaitTest = true; coBubble('coach', 'Good — here\'s a plan from your answers for now. When the test is in, I\'ll rebuild it with your results.'); }
    coBuildAndShow(null);
  });
}
export function coBuildAndShow(test) {
  const plan = coachBuild(S.coach.answers, test);
  if (!plan) return coBubble('coach', 'I need at least one training day to build a plan.');
  S.coach.draft = plan; save();
  coPreview(plan);
}
/* The plan as day cards, with Swap on each exercise and Accept. */
function coPreview(plan, readOnly) {
  const fmtX = x => x.event ? `${x.sets} × 20 m carry` : `${x.sets} × ${x.reps[0]}–${x.reps[1]} @ RIR ${x.rir}`;
  const dayHtml = (d, di, w) => (d[w] || []).map((x, xi) => `<div class="co-x"><div class="grow"><b>${esc(candName(x.key))}</b>
      <div class="sub">${fmtX(x)}${x.notes.length ? ` · ${esc(x.notes.join(' · '))}` : ''}</div></div>
      ${!readOnly && x.alts.length ? `<button class="btn xs ghost" data-coswap="${di}|${w}|${xi}" aria-label="Swap ${esc(candName(x.key))}">Swap</button>` : ''}</div>`).join('');
  coBubble('coach', `<b>${esc(plan.name)}</b> · ${plan.days.length} day${plan.days.length === 1 ? '' : 's'} · ${plan.minutes} min · ${plan.weeks} weeks${plan.days[0].B ? ' · A/B weeks' : ''}
    ${plan.changes.length ? `<ul class="fit-flags" style="margin:6px 0">${plan.changes.map(c => `<li>${esc(c)}</li>`).join('')}</ul>` : ''}
    ${plan.warnings.map(w => `<div class="sub" style="color:var(--gold);margin:4px 0">⚠ ${esc(w)}</div>`).join('')}
    <div id="coPlan">${plan.days.map((d, di) => `<div class="co-day"><div class="row between"><b>${esc(COACH_WD.find(w => w[0] === d.wd)[1])} · ${esc(d.name)}</b><span class="sub">${esc(d.placeName)}</span></div>
      ${d.B ? `<div class="eyebrow" style="margin-top:4px">A week</div>${dayHtml(d, di, 'A')}<div class="eyebrow" style="margin-top:6px">B week</div>${dayHtml(d, di, 'B')}` : dayHtml(d, di, 'A')}</div>`).join('')}</div>`);
  const log = $('#coLog', CO.bg), card = log.lastElementChild;
  card.querySelectorAll('[data-coswap]').forEach(b => b.onclick = () => coSwap(plan, b.dataset.coswap));
  if (readOnly) return coMenu();
  const ai = aiStatus(), tailored = !!plan.tailored;
  coAnswer(`${coChips([['accept', 'Accept — put it on my calendar'], ...(ai === 'on' && !tailored ? [['tailor', 'Tailor it with Claude']] : []), ['answers', 'Change my answers']])}
    <div class="sub" style="margin-top:6px">Nothing changes until you accept. Weights fill in from your history and your first RIR sets.${ai !== 'on' && !tailored ? ' <i>Tailor it</i> — Claude fitting the plan to your log — needs your AI key (Settings → AI).' : ''}</div>`);
  $('#coAns', CO.bg).querySelectorAll('[data-cov]').forEach(b => b.onclick = () => {
    coBubble('me', esc(b.textContent));
    if (b.dataset.cov === 'answers') return coAnswers();
    if (b.dataset.cov === 'tailor') return coTailor(plan);
    coachAccept(plan, n => {
      coBubble('coach', `Done — ${n} session${n === 1 ? '' : 's'} on your calendar, starting ${esc(relDay(S.workouts.filter(w => w.prog === 'coach-' + plan.id && w.status === 'planned').map(w => w.date).sort()[0] || today()).toLowerCase())}. Open me any time to change it.`);
      coMenu();
    });
  });
}
/* Tailor it (coach-spec §4): one Claude call over the built plan and the
   training digest. Claude may only pick swaps from each slot's own swap list
   and move set counts by one; every answer is re-checked here and anything
   that fails is dropped. Shown as a diff; nothing changes until accepted. */
export function coTailorPrompt(plan) {
  const D = coachDigest(), C = S.coach, A = C.answers || {};
  const slots = [];
  plan.days.forEach((d, di) => ['A', 'B'].forEach(w => (d[w] || []).forEach((x, si) => slots.push({
    day: di, week: w, slot: si, name: `${d.name}${d.B ? ' ' + w : ''}`, exercise: x.key, role: x.role, sets: x.sets,
    reps: x.reps ? x.reps.join('-') : 'carry', rir: x.rir, can_swap_to: x.alts.slice(0, 5) }))));
  return {
    system: 'You tailor a strength plan inside the Ironlog app. Reply with JSON only: {"changes":[{"day":0,"week":"A","slot":2,"swap":"movement/equipment or null","sets":3 or null,"reason":"one short line"}]}. '
      + 'Rules: at most 6 changes; only change something the lifter\'s data gives a reason for (a stalled or lagging lift, low volume for a muscle, fitting-test flags, notes, goal); '
      + '"swap" must be one of that slot\'s can_swap_to values exactly; "sets" may only be the current sets plus or minus 1; never touch a main lift\'s exercise unless it is stalled; '
      + 'no medical or injury advice. If nothing needs changing, reply {"changes":[]}.',
    user: JSON.stringify({
      lifter: { goal: A.goal, experience: A.experience, minutes: A.minutes, go_easy_on: A.easy || [], notes: C.notes || [] },
      log: { lifts: D.lifts.map(l => ({ name: l.name, e1rm_kg: l.now && +l.now.toFixed(1), stalled: !!l.stall })),
        sets_per_muscle_this_week: Object.fromEntries(Object.entries(D.muscles).map(([k, v]) => [MUSCLES[k] || k, +v.toFixed(1)])),
        rir_vs_target: D.rirGap != null ? +D.rirGap.toFixed(1) : null,
        fitting_test: D.testR ? { profile: D.testR.type, flags: D.testR.flags.map(f => f.text) } : null },
      plan: slots }),
  };
}
/* Keep only what passes the local rules; say how many were dropped. */
export function coTailorCheck(plan, reply) {
  const keep = [], easy = (S.coach.answers || {}).easy || [];
  let dropped = 0;
  (Array.isArray(reply && reply.changes) ? reply.changes : []).slice(0, 6).forEach(c => {
    const d = plan.days[c.day], list = d && d[c.week === 'B' ? 'B' : 'A'], x = list && list[c.slot];
    if (!x) { dropped++; return; }
    const out = { day: c.day, week: c.week === 'B' ? 'B' : 'A', slot: c.slot, reason: String(c.reason || '').slice(0, 140) };
    if (c.swap && c.swap !== x.key) {
      const others = list.filter((y, i) => i !== c.slot).map(y => y.key);
      if (!x.alts.includes(c.swap) || !coachOk(c.swap, coachPlace(d.placeId), { easy }, others)) { dropped++; return; }
      out.swap = c.swap;
    }
    if (c.sets != null && +c.sets !== x.sets) {
      const n = Math.round(+c.sets);
      if (!(Math.abs(n - x.sets) === 1 && n >= 1 && n <= 6)) { if (!out.swap) { dropped++; return; } }
      else out.sets = n;
    }
    if (out.swap || out.sets) keep.push(out);
  });
  return { keep, dropped };
}
async function coTailor(plan) {
  coBubble('coach', '<span class="co-typing" aria-label="Claude is working">•••</span>');
  const dots = $('#coLog', CO.bg).lastElementChild;
  let res;
  try {
    const p = coTailorPrompt(plan);
    const r = await aiCall({ feature: 'tailor', system: p.system, user: p.user, maxTokens: 1500 });
    res = coTailorCheck(plan, planParse(r.text));
  } catch (e) {
    dots.remove();
    coBubble('coach', esc(e.nokey || e.capped || e.net || e.status ? aiWhy(e) : 'Claude\'s reply didn\'t make sense, so I\'ve kept the plan as it is.'));
    return coPreviewChips(plan);
  }
  dots.remove();
  coTailorShow(plan, res);
}
function coTailorShow(plan, res) {
  if (!res.keep.length) {
    coBubble('coach', `Claude had nothing to change${res.dropped ? ` that passed my checks (${res.dropped} suggestion${res.dropped === 1 ? '' : 's'} broke a rule and were dropped)` : ' — the plan already fits your log'}.`);
    plan.tailored = true; S.coach.draft = plan; save();
    return coPreviewChips(plan);
  }
  const line = c => {
    const d = plan.days[c.day], x = d[c.week][c.slot];
    const what = [c.swap ? `${candName(x.key)} → <b>${esc(candName(c.swap))}</b>` : `<b>${esc(candName(x.key))}</b>`, c.sets ? `${x.sets} → ${c.sets} sets` : ''].filter(Boolean).join(', ');
    return `• ${esc(d.name)}${d.B ? ' ' + c.week : ''}: ${what}${c.reason ? `<div class="sub">${esc(c.reason)}</div>` : ''}`;
  };
  coBubble('coach', `<b>Claude suggests ${res.keep.length} change${res.keep.length === 1 ? '' : 's'}:</b><br>${res.keep.map(line).join('<br>')}${res.dropped ? `<div class="sub" style="margin-top:4px">${res.dropped} more broke a rule (kit, go-easy list, same-day clash, or too big a jump) and were dropped.</div>` : ''} <span class="chip blue">CLAUDE</span>`);
  coAnswer(`${coChips([['use', 'Use these changes'], ['keep', 'Keep the original']], null, true)}`);
  $('#coAns', CO.bg).querySelectorAll('[data-cov]').forEach(b => b.onclick = () => {
    coBubble('me', esc(b.textContent));
    plan.tailored = true;
    if (b.dataset.cov === 'use') {
      res.keep.forEach(c => {
        const x = plan.days[c.day][c.week][c.slot];
        if (c.swap) { x.alts = [x.key, ...x.alts.filter(a => a !== c.swap)]; x.key = c.swap; x.notes = [...x.notes.filter(n => !/^tailored/.test(n)), 'tailored'].filter(Boolean); }
        if (c.sets) x.sets = c.sets;
      });
      plan.changes = [...plan.changes, `Tailored by Claude: ${res.keep.length} change${res.keep.length === 1 ? '' : 's'}.`];
    }
    S.coach.draft = plan; save();
    coPreview(plan);
  });
}
/* The preview's own buttons, without redrawing the plan. */
function coPreviewChips(plan) {
  const log = $('#coLog', CO.bg);
  const card = [...log.querySelectorAll('.co-b.coach')].reverse().find(b => b.querySelector('#coPlan'));
  if (!card) return coPreview(plan);
  const keepLog = log.innerHTML;
  coPreview(plan);
  log.innerHTML = keepLog;   // the plan is already on screen; only the buttons were needed
  log.querySelectorAll('[data-coswap]').forEach(b => b.onclick = () => coSwap(plan, b.dataset.coswap));
}
function coSwap(plan, ref) {
  const [di, w, xi] = ref.split('|'), d = plan.days[+di], list = d[w], x = list[+xi];
  modal({
    title: `Swap ${candName(x.key)}`,
    body: x.alts.map(c => `<button class="axrow" data-coalt="${esc(c)}"><span class="lbl">${esc(candName(c))}</span></button>`).join(''),
    foot: '<button class="btn ghost" data-close>Cancel</button>',
    onOpen: bg => bg.querySelectorAll('[data-coalt]').forEach(b => b.onclick = () => {
      const c = b.dataset.coalt, place = coachPlace(d.placeId);
      const others = list.filter((y, i) => i !== +xi).map(y => y.key);
      if (!coachOk(c, place, { easy: S.coach.answers.easy || [] }, others)) return toast('That clashes with something else that day');
      x.alts = [x.key, ...x.alts.filter(a => a !== c)]; x.key = c;
      S.coach.draft = plan; save(); closeModal();
      const row = $(`[data-coswap="${ref}"]`, CO.bg);
      if (row) row.closest('.co-x').querySelector('b').textContent = candName(c);
    }),
  });
}
/* Every answer, pre-filled; change one and go straight back to building. */
