  /* Missed days, not sessions: two programs planning the same day count once,
     and a day with a session logged isn't missed. The coach's own plan wins
     when there is one. */
  const prog = S.coach && S.coach.planProg && S.programs.includes(S.coach.planProg) ? S.coach.planProg : null;
  const doneDays = new Set(coLifted(7).map(w => w.date));
  /* Skipped sessions are off the plan, so their records count too. A moved
     session isn't a missed one: it's still coming. */
  const skips = (S.misses || []).filter(m => !m.movedTo && m.date < t && daysBetween(m.date, t) < 7 && (!prog || m.prog === prog));
  const missed = [...new Set([...S.workouts.filter(w => w.status === 'planned' && w.date < t && daysBetween(w.date, t) < 7
    && (!prog || w.prog === prog)).map(w => w.date), ...skips.map(m => m.date)].filter(d => !doneDays.has(d)))];
  const whyMissed = {};
  (S.misses || []).filter(m => m.date <= t && daysBetween(m.date, t) < 7).forEach(m => { whyMissed[m.reason] = (whyMissed[m.reason] || 0) + 1; });
  const lifts = mainLiftKeys().map(k => ({ key: k, name: leafName(k), now: historyE1(k), then: historyE1(k, addDaysISO(t, -14)), stall: stallFor(k), last: lastSession(k) }));
  const mus = {};
  wk.forEach(wo => sessionMuscles(wo).list.forEach(m => { mus[m.key] = (mus[m.key] || 0) + m.sets; }));
  const gaps = [], vgaps = [];
  coLifted(14).forEach(wo => wo.exercises.forEach(e => e.sets.forEach(s => {
    if (!s.done || !isWorking(s) || s.rpe == null) return;
    if (s.t != null) gaps.push(rpeToRir(s.rpe) - s.t);
    if (vbtEst(s.vbt, s) && !rirFromSensor(s)) vgaps.push(rpeToRir(s.rpe) - rpeToRir(s.vbt.est.rpe));   // a sensor-filled RIR agrees with itself
  })));
  let streak = 0;
  for (let i = 0; i < 26; i++) { if (coLifted(7, addDaysISO(t, -7 * i)).length) streak++; else break; }
  const ev = (S.meets || []).filter(m => m.date >= t).sort((a, b) => a.date < b.date ? -1 : 1)[0] || null;
  const test = fitTestsSorted().pop() || null;
  const next = S.workouts.filter(w => w.status === 'planned' && w.date >= t).sort((a, b) => a.date < b.date ? -1 : 1)[0] || null;
