  if (D.rirGap != null && D.rirGap > 1) { why.push(`your sets have been ${D.rirGap.toFixed(1)} reps easier than planned — the weight may be too light to drive progress`); fix.push('push the top set closer to its RIR target'); }
  if (D.ci.sleep && D.ci.sleep < 7) { why.push(`sleep has averaged ${nice(D.ci.sleep)} h this week`); fix.push('sleep is the cheapest win — aim for 7–9 h'); }
  if (D.bwThen && D.ci.weight && D.ci.weight < D.bwThen - 1) { why.push(`bodyweight is down ${coKg(D.bwThen - D.ci.weight)} in a month`); fix.push('strength rarely climbs while weight drops — eat to maintain for now'); }
  const leaf = keyLeaf(key), lm = leaf ? leafMuscles(leaf) : null, prime = lm && lm.m ? Object.entries(lm.m).sort((a, b) => b[1] - a[1])[0][0] : null;
  if (prime && (D.muscles[prime] || 0) < CO_LOW_SETS) { why.push(`${MUSCLES[prime] || prime} got only ${nice(D.muscles[prime] || 0)} working sets this week`); fix.push(`add 2–4 sets for ${(MUSCLES[prime] || prime).toLowerCase()}`); }
  if (D.week.missed) why.push(`${D.week.missed} planned session${D.week.missed === 1 ? '' : 's'} missed this week`);
  if (D.streak >= 8) { why.push(`you've trained ${D.streak} weeks straight`); fix.push('a lighter week could let it come back up'); }
