  return { html: `<b>${name}</b> has stalled since ${esc(fmtDate(s.since))}.<br>${why.length ? `Likely reasons: ${why.map(esc).join('; ')}.` : 'Nothing obvious in your log — plateaus happen.'}<br>What to try: ${fix.map(esc).join('; ')}.`,
    act: coSuggestion('swap', key) ? [[`sugg:swap:${key}`, 'Swap it in my plan']] : [] };
