  if (stalls) pts.push([stalls >= 2 ? 2 : 1, `${stalls} main lift${stalls === 1 ? '' : 's'} stalled`]);
  if (D.rirGap != null && D.rirGap < -0.5) pts.push([1, 'sets finishing closer to failure than planned']);
  if (D.ci.sleep && D.ciPrev.sleep && D.ci.sleep < D.ciPrev.sleep - 0.5) pts.push([1, `sleep down to ${nice(D.ci.sleep)} h`]);
  if (D.ci.energy && D.ciPrev.energy && D.ci.energy < D.ciPrev.energy - 0.5) pts.push([1, `energy down to ${nice(D.ci.energy)}/5`]);
  if (D.ci.soreness && D.ci.soreness >= 3.5) pts.push([1, `soreness ${nice(D.ci.soreness)}/5`]);
