  const lines = [], next = [];
  const work = wo.exercises.map(e => ({ e, sets: e.sets.filter(s => isWorking(s)) })).filter(x => x.sets.length);
  const done = work.reduce((a, x) => a + x.sets.filter(s => s.done).length, 0), all = work.reduce((a, x) => a + x.sets.length, 0);
  const skipped = work.filter(x => !x.sets.some(s => s.done)).map(x => exName(x.e));
  if (wo.prog) lines.push(`${done} of ${all} planned sets done${skipped.length ? `; skipped ${skipped.join(', ')}` : ''}.`);
  else { const T = sessionTotals(wo); lines.push(`${T.sets} working set${T.sets === 1 ? '' : 's'} over ${work.length} exercise${work.length === 1 ? '' : 's'}, ${wt(T.volume, 0)} moved.`); }
  const main = work[0];
