/* Follow-ups worth offering after each kind of answer. */
const CO_NEXT = {
  today: [['short', 'Short on time'], ['home', 'At home today'], ['motivate', 'Not feeling it']],
  review: [['debrief', 'Debrief my last session'], ['volume', 'My volume'], ['deload', 'Should I deload?']],
  debrief: [['review', 'Review my week'], ['today', 'Next session']],
  stall: [['deload', 'Should I deload?'], ['volume', 'My volume']],
  deload: [['recovery', 'My recovery'], ['review', 'Review my week']],
  volume: [['weak', 'Weakest area'], ['review', 'Review my week']],
  weak: [['volume', 'My volume'], ['stall', 'Anything stalled?']],
  recovery: [['deload', 'Should I deload?']],
  body: [['review', 'Review my week']],
  event: [['today', 'Next session'], ['deload', 'Should I deload?']],
  missed: [['today', 'Next session']],
  motivate: [['short', 'Short session'], ['today', 'Today\'s session']],
  short: [['today', 'Full session']],
  prs: [['review', 'Review my week']],
  count: [['review', 'Review my week']],
};

/* One answer, as a coach bubble plus any follow-up chips. */
export function coAnswerTopic(topic, arg) {
  const D = coachDigest();
  let r;
  if (topic === 'greet') r = coAnsGreet(D);
  else if (topic === 'thanks') r = { html: coPick(['Any time.', 'Go get it.', 'No problem — shout if you need me.', 'Good luck with it.']) };
  else if (topic === 'nothanks') r = { html: coPick(['No problem.', 'Fair enough.', 'OK — I\'m here if you need me.']) };
  else if (topic === 'okay') r = { html: coPick(['Sure — what next?', 'OK. Anything else?', 'Right — what do you want to know?']) };
  else if (topic === 'help') r = coAnsHelp();
  else if (topic === 'who') r = coAnsWho();
  else if (topic === 'motivate') r = coAnsMotivate(D);
  else if (topic === 'missed') r = coAnsMissed(D);
  else if (topic === 'short') r = coAnsShort(D, arg);
  else if (topic === 'home') r = coAnsHome(D);
  else if (topic === 'weightfor') r = coAnsWeightFor(D, arg && arg.includes('/') ? arg : (CO && CO.ctx && CO.ctx.lift), CO && CO.lastText);
  else if (topic === 'warmup') r = coAnsWarmup(D, arg && arg.includes('/') ? arg : (CO && CO.ctx && CO.ctx.lift));
  else if (topic === 'max') r = coAnsMax(D, arg && arg.includes('/') ? arg : (CO && CO.ctx && CO.ctx.lift));
  else if (topic === 'plates') r = coAnsPlates(arg);
  else if (topic === 'prs') r = coAnsPrs();
  else if (topic === 'count') r = coAnsCount(D);
  else if (topic === 'convert') r = coAnsConvert(arg);
  else if (topic === 'rirrpe') r = coAnsRirRpe(arg);
  else if (topic === 'pain') r = coAnsPain();
  else if (topic === 'gear') r = coAnsGear(D, arg);
  else if (topic === 'glossary') r = coAnsGlossary(arg);
  else if (topic === 'restq') r = coAnsRest();
  else if (topic === 'reps' || topic === 'sets') r = coAnsRepsSets(topic);
  else if (topic === 'progress') r = coAnsProgress(D);
  else if (topic === 'failure') r = coAnsFailure();
  else if (topic === 'standards') r = coAnsStandards(D, coFindLift(' ' + String(arg || '').toLowerCase() + ' ') || (arg && String(arg).includes('/') ? arg : null));
  else if (topic === 'points') r = coAnsPoints();
  else if (topic === 'goal') r = coAnsGoal();
  else if (topic === 'openers') r = coAnsOpeners(D);
  else if (topic === 'length') r = coAnsLength();
  else if (topic === 'nutrition') r = coAnsNutrition();
  else if (topic === 'supps') r = coAnsSupps();
  else if (topic === 'cardioq') r = coAnsCardio();
  else if (topic === 'mobility') r = coAnsMobility();
  else if (topic === 'balanceq') r = coAnsBalance();
  else if (topic === 'fittest') r = coAnsFitTest();
  else if (topic === 'sleepbad') r = coAnsSleepBad(D);
  else if (topic === 'ill') r = coAnsIll();
  else if (topic === 'travel') r = coAnsTravel();
  else if (topic === 'consecutive') r = coAnsConsecutive();
  else if (topic === 'tonnage') r = coAnsTonnage();
  else if (topic === 'lasttrained') r = coAnsLastTrained(arg);
  else if (topic === 'days') r = coAnsDays();
  else if (topic === 'skip') r = coAnsSkip(D);
  else if (topic === 'reschedule') r = coAnsReschedule(D);
  else if (topic === 'dislike') r = coAnsDislike(arg);
  else if (topic === 'swapreq') { r = coAnsSwapReq(D, arg); if (r.html == null) return; }
  else if (topic === 'bye') r = { html: coPick(['See you — train well.', 'Later. Go get it.', 'Bye — I\'m here when you need me.']) };
  else if (topic === 'laugh') r = { html: coPick(['😄', 'Ha.', '🙂 Anything else?']) };
  else if (topic === 'why') r = coAnsWhy();
  else if (topic === 'today') r = coAnsToday(D);
  else if (topic === 'review') { r = coReview(D); S.coach.lastReview = D.t; save(); }
  else if (topic === 'debrief') r = coDebrief(arg ? S.workouts.find(w => w.id === arg) : D.lastDone);
  else if (topic === 'stall') r = arg ? coAnsStall(D, arg) : (D.lifts.find(l => l.stall) ? coAnsStall(D, D.lifts.find(l => l.stall).key) : { html: 'None of your main lifts is stalled — each has beaten its mark within its last five sessions.' });
  else if (topic === 'lift') {
    /* "how's my deadlift" with no deadlift logged: say so, then the main lifts. */
    const named = !arg && CO && CO.lastText && (String(CO.lastText).toLowerCase().match(/\b(deadlift|bench|squat|overhead press|ohp|row|curl|pull-?up|log press)\b/) || [])[1];
    r = arg ? coAnsLift(D, arg) : { html: `${named ? `No ${esc(named)} logged yet.${D.lifts.length ? ' Your main lifts:<br>' : ''}` : ''}${D.lifts.map(coLiftLine).join('<br>') || (named ? '' : 'No main lifts logged yet.')}` };
  }
  else if (topic === 'deload') r = coAnsDeload(D);
  else if (topic === 'weak') r = coAnsWeak(D);
  else if (topic === 'event') r = coAnsEvent(D);
  else if (topic === 'volume') r = coAnsVolume(D);
  else if (topic === 'recovery') r = coAnsRecovery(D);
  else if (topic === 'body') r = coAnsBody(D);
  else if (topic === 'plan') r = coAnsPlan();
  else if (topic === 'faq') r = { html: `<b>${esc(arg[0])}</b><br>${esc(arg[1])}` };
  else return;
  coBubble('coach', r.html + (debugOn() ? ' ' + why('digest') : ''));
  /* Remember what this was about, so "and my squat?" and "why?" work next. */
  const lift = arg && String(arg).includes('/') && !String(arg).includes(' ') ? arg : null;
  if (['why', 'thanks', 'nothanks', 'okay', 'greet', 'help', 'who', 'bye', 'laugh'].includes(topic)) return coFollow(r.act || []);   // small talk keeps the thread
  CO.ctx = { topic, lift: lift || (CO.ctx || {}).lift || null, because: r.because || null, next: (r.act || [])[0] ? String(r.act[0][0]).split(':') : null };
  if (topic === 'stall' && !r.because) CO.ctx.because = 'A lift counts as stalled when, over its last five sessions, none of the last four beat the first by more than 1% (e1RM, off days left out). The reasons come from your RIR against targets, sleep, bodyweight, the muscle\'s weekly sets and missed sessions.';
  if (topic === 'deload' && !r.because) { const s = coDeloadScore(D); CO.ctx.because = s.pts.length ? `Score ${s.score}: ${s.pts.map(p => `${p[1]} (+${p[0]})`).join(', ')}. 3 or more says take a lighter week.` : 'Nothing in your log adds to the deload score — no stalls, effort on target, sleep and energy steady.'; }
  if (topic === 'lift' && lift) CO.ctx.because = 'e1RM is Epley with your reps in reserve added to the reps, capped at 12. The working figure is your last three sessions, newest weighted most.';
  const seen = new Set();
  const act = [...(r.act || []), ...(CO_NEXT[topic] || [])].filter(([v]) => !seen.has(v) && seen.add(v)).slice(0, 4);
  coFollow(act);
}
/* Follow-up chips under an answer, then the usual menu. */
function coFollow(act) {
  if (!act.length) return coMenu();
  coAnswer(`${coChips([...act, ['menu', 'Something else']], null, true)}${coFormHtml()}`);
  $('#coAns', CO.bg).querySelectorAll('[data-cov]').forEach(b => b.onclick = () => coMenuPick(b.dataset.cov, b.textContent));
  coFormWire();
}
/* The typed-question box sits under every set of chips. */
function coFormHtml() {
  return `<form class="row" id="coForm" style="gap:6px;margin-top:10px"><label for="coText" class="sr-only">Ask the coach</label>
    <input id="coText" autocomplete="off" placeholder="Ask about your training…" style="flex:1"><button class="btn sm primary" type="submit">Ask</button></form>`;
}
function coFormWire() {
  const f = $('#coForm', CO.bg);
  if (f) f.onsubmit = ev => { ev.preventDefault(); const t = $('#coText', CO.bg).value.trim(); if (t) coTyped(t); };
}
/* Typed into the chat: the local matcher first, then (with a key) the AI. */
async function coTyped(text) {
  coBubble('me', esc(text));
  CO.lastText = text;
  const m = coMatch(text);
  if (m && m.topic === 'remember') {
    coBubble('coach', `Remember this? "${esc(m.arg)}"`);
    coAnswer(coChips([['yes', 'Yes, remember it'], ['no', 'No']]));
    $('#coAns', CO.bg).querySelectorAll('[data-cov]').forEach(b => b.onclick = () => {
      coBubble('me', esc(b.textContent));
      if (b.dataset.cov === 'yes') { const C = coachMem(); C.notes = [...C.notes, m.arg].slice(-20); save(); coBubble('coach', 'Saved. You can see and delete notes in Coach settings.'); }
      coMenu();
    });
    return;
  }
  if (m) {
    /* A short pause reads as the coach thinking, not a lookup. */
    coBubble('coach', '<span class="co-typing" aria-label="Coach is typing">•••</span>');
    const dots = $('#coLog', CO.bg).lastElementChild;
    await new Promise(r => setTimeout(r, 300 + Math.random() * 300));
    dots.remove();
    return coAnswerTopic(m.topic, m.arg);
  }
  if (aiStatus() !== 'on') {
    coBubble('coach', `I can't answer that one on my own yet${aiStatus() === 'capped' ? ' (and this month\'s AI cap is reached)' : ' — with your AI key added I could try'}. These I can do:`);
    return coMenu();
  }
  coBubble('coach', '…');
  const thinking = $('#coLog', CO.bg).lastElementChild;
  try {
    const D = coachDigest(), C = S.coach;
    const facts = {
      goal: (C.answers || {}).goal, experience: (C.answers || {}).experience, notes: C.notes, week: D.week,
      lifts: D.lifts.map(l => ({ name: l.name, e1rm_kg: l.now && +l.now.toFixed(1), two_weeks_ago_kg: l.then && +l.then.toFixed(1), stalled: !!l.stall })),
      sets_per_muscle_this_week: Object.fromEntries(Object.entries(D.muscles).map(([k, v]) => [MUSCLES[k] || k, +v.toFixed(1)])),
      rir_vs_target: D.rirGap != null ? +D.rirGap.toFixed(1) : null, checkins_this_week: D.ci, checkins_last_week: D.ciPrev,
      event: D.event ? { name: D.event.name, date: D.event.date } : null, block: D.block ? { kind: D.block.kind.label, week: D.block.week } : null,
      fitting_test: D.testR ? { profile: D.testR.type, flags: D.testR.flags.map(f => f.text) } : null,
    };
    const r = await aiCall({ feature: 'ask', maxTokens: 400,
      system: 'You are the coach inside Ironlog, a strength training log. Answer the lifter\'s question in under 120 words of plain text (no markdown). Use only the numbers in the training data given; if they don\'t answer it, say what to log. Training topics only. No medical or injury advice: for pain or injury, say to stop and see a professional. RIR means reps in reserve. Weights are kg.',
      user: `Training data: ${JSON.stringify(facts)}\n\nQuestion: ${text}` });
    thinking.textContent = r.text.trim() || 'No answer came back.';
    thinking.insertAdjacentHTML('beforeend', ' <span class="chip blue" style="margin-left:4px">CLAUDE</span>');
  } catch (e) { thinking.textContent = aiWhy(e); }
  coMenu();
}
/* The coach's Home card: the weekly review, once a week. */
export function coachHomeCard() {
  const C = S.coach;
  if (!C || !C.setupDone) return '';
  const last = C.lastReview;
  if (last && daysBetween(last, today()) < 7) return '';
  if (!coLifted(7).length) return '';
  return `<div class="card" style="margin-bottom:13px"><div class="row between" style="gap:8px"><div class="grow"><div class="eyebrow">Coach</div>
    <div style="font-weight:650">Your weekly review is ready</div><div class="sub">What moved, what's stuck, and one focus for next week.</div></div>
    <button class="btn sm primary" id="hmReview">Open</button></div></div>`;
}

/* ---------------- plans from anywhere: the Ironlog plan format (r&d/specs/plan-format.md) ----------------
   A short JSON format any AI can write: the lifter copies the rules into their
   own AI app with their plan, or Claude writes it here on their key, or they
   paste or load a file. planToProgram() turns it into a normal program and
   reports anything it had to guess before it's installed. */
const PLAN_EQ_WORDS = { dumbbell: 'dumbbells', db: 'dumbbells', dbs: 'dumbbells', kettlebells: 'kettlebell', kb: 'kettlebell', band: 'resistance_band', bands: 'resistance_band',
  resistance_bands: 'resistance_band', trapbar: 'trap_bar', hex_bar: 'trap_bar', smith_machine: 'smith', cables: 'cable', machines: 'machine', bw: 'bodyweight',
  plate_loaded: 'plate_loaded_machine', ssb: 'safety_squat_bar', safety_bar: 'safety_squat_bar', barbells: 'barbell',
  grippers: 'gripper', hand_gripper: 'gripper', extension_bands: 'extension_band', finger_band: 'extension_band', finger_bands: 'extension_band' };
const PLAN_DEFAULT_DAYS = { 1: ['mon'], 2: ['mon', 'thu'], 3: ['mon', 'wed', 'fri'], 4: ['mon', 'tue', 'thu', 'fri'], 5: ['mon', 'tue', 'wed', 'thu', 'fri'], 6: ['mon', 'tue', 'wed', 'thu', 'fri', 'sat'], 7: ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'] };
/* The rules, as given to an AI. r&d/specs/plan-format.md mirrors this text. */
export function planFormatText() {
  const V = catalogue().V, eq = (V.equipment || []).map(e => e.id || e);
  const moves = (catalogue().C.movements || []).filter(m => m.type !== 'cardio')
    .map(m => `${m.name} — ${(m.equipment || []).join(', ')}`).sort();
  return `You are writing a training plan for the Ironlog app. Reply with one JSON object and nothing else — no prose, no code fences.

FORMAT
{
  "format": "ironlog-plan", "version": 1,
  "name": "Short plan name",
  "weeks": 8,                              // how many weeks to put on the calendar (1-52)
  "weekdays": ["mon", "wed", "fri"],       // optional: one per day below, in order (mon tue wed thu fri sat sun)
  "days": [
    { "name": "Push", "exercises": [
      { "name": "Bench Press", "equipment": "barbell", "sets": 3, "reps": "6-10", "rir": 2 },
      { "name": "Triceps Pushdown", "equipment": "cable", "sets": 3, "reps": 12, "rir": 1, "notes": "superset with Lateral Raise" },
      { "name": "Back Squat", "sets": [ { "reps": 5, "rir": 4, "type": "warmup" }, { "reps": 3, "rir": 1, "type": "top" }, { "reps": 5, "rir": 2, "type": "backoff" } ] },
      { "name": "Plank", "sets": 3, "seconds": 45 },
      { "name": "Farmers Carry", "equipment": "farmers_handles", "sets": 3, "metres": 20, "kg": 60 }
    ] }
  ],
  "alternate": { "days": [ ... ] }         // optional: a B week, same number of days; odd weeks use "days", even weeks these
}

RULES
- Exercise names: use a name from the list below wherever one fits, with an equipment value that list allows for it. Anything else is added as the lifter's own exercise.
- equipment is one of: ${eq.join(', ')}. Leave it out for the usual version.
- "unilateral": true for single-arm or single-leg work.
- sets is a number (every set the same) or a list of sets. Each set can have reps, rir, kg, type, seconds, metres.
- reps is a number or a range like "6-10". A range starts at the bottom and the lifter adds weight at the top.
- rir is reps in reserve: 0 = failure, 2 = two left. Prefer rir to fixed weights — Ironlog works out the weight from the lifter's history. Only give kg when the plan really fixes a load.
- type: warmup, working (default), top, backoff, amrap, drop.
- Holds: "seconds" instead of reps. Carries and sleds: "metres" (and kg).
- notes: free text shown with the exercise. Ironlog reads "superset with <exercise>", "tempo 3-1-1-0" and "paused" from it.
- Training days per week: 1-7. Keep each day to what fits the lifter's time.
- No medical advice; programme around injuries only as the lifter asks.

EXERCISES (name — equipment it allows)
${moves.join('\n')}`;
}
function planEq(v) {
  if (!v) return null;
  const k = String(v).trim().toLowerCase().replace(/[\s-]+/g, '_');
  return PLAN_EQ_WORDS[k] || k;
}
/* Pull the JSON object out of whatever came back (an AI may wrap it in prose or fences). */
export function planParse(text) {
  const t = String(text || '').replace(/```(?:json)?/g, '').trim();
  const a = t.indexOf('{'), z = t.lastIndexOf('}');
  if (a < 0 || z <= a) throw new Error('No plan found — paste the JSON your AI wrote (it starts with {).');
  try { return JSON.parse(t.slice(a, z + 1)); }
  catch (e) { throw new Error(`That isn't valid JSON (${e.message}). Ask your AI to send the plan again as JSON only.`); }
}
/* Either the plan format or a full Ironlog program → a program, plus what was guessed. */
export function planToProgram(obj) {
  const warn = [], unknown = new Set(), V = catalogue().V, eqOk = new Set((V.equipment || []).map(e => e.id || e));
  const id = 'import-' + uid();
  if (Array.isArray(obj.workouts)) {                       // already a program (program.json shape)
    if (!obj.workouts.length || !obj.workouts.every(w => Array.isArray(w.exercises))) throw new Error('The program has no sessions with exercises.');
    obj.workouts.forEach(w => w.exercises.forEach(e => { if (!resolveName(e.name)) unknown.add(e.name); }));
    return { P: { ...obj, id, name: obj.name || 'Imported program' }, warn, unknown: [...unknown] };
  }
  const days = obj.days;
  if (!Array.isArray(days) || !days.length) throw new Error('The plan has no days. Each day needs a name and a list of exercises.');
  if (days.length > 7) throw new Error(`${days.length} days a week — the most is 7.`);
  const alt = obj.alternate && Array.isArray(obj.alternate.days) ? obj.alternate.days : null;
  if (alt && alt.length !== days.length) { warn.push(`The B week has ${alt.length} day${alt.length === 1 ? '' : 's'} but the plan has ${days.length} — B weeks left out.`); }
  const B = alt && alt.length === days.length ? alt : null;
  let weeks = Math.round(+obj.weeks || 8);
  if (!(weeks >= 1 && weeks <= 52)) { warn.push(`"weeks" was ${obj.weeks} — using 8.`); weeks = 8; }
  const wdKeys = COACH_WD.map(w => w[0]);
  let wd = Array.isArray(obj.weekdays) ? obj.weekdays.map(d => String(d).slice(0, 3).toLowerCase()) : null;
  if (wd && (wd.length !== days.length || wd.some(d => !wdKeys.includes(d)))) { warn.push('The weekdays didn\'t match the days — placed them for you.'); wd = null; }
  if (!wd) { wd = PLAN_DEFAULT_DAYS[days.length]; if (!Array.isArray(obj.weekdays)) warn.push(`No weekdays given — put on ${wd.map(d => COACH_WD.find(w => w[0] === d)[1]).join(', ')}.`); }
  let anyKg = false;
  const ex = e => {
    const name = String(e.name || '').trim();
    if (!name) throw new Error('An exercise has no name.');
    if (!resolveName(name)) unknown.add(name);
    let eq = planEq(e.equipment);
    if (eq && !eqOk.has(eq)) { warn.push(`${name}: "${e.equipment}" isn't equipment Ironlog knows — used the usual version.`); eq = null; }
    const base = { reps: e.reps, rir: e.rir, kg: e.kg, type: e.type, seconds: e.seconds, metres: e.metres };
    const list = Array.isArray(e.sets) ? e.sets.map(s => ({ ...base, ...s })) : Array.from({ length: clamp(Math.round(+e.sets || 3), 1, 20) }, () => ({ ...base }));
    const notes = [];
    let range = null;
    const sets = list.map(s => {
      let r = null;
      const rr = String(s.reps ?? '').match(/^\s*(\d{1,3})\s*(?:-|–|to)\s*(\d{1,3})\s*$/);
      if (rr) { r = +rr[1]; range = range || [+rr[1], +rr[2]]; } else if (+s.reps > 0) r = Math.round(+s.reps);
      const type = String(s.type || 'working').toLowerCase().replace(/[^a-z]/g, '');
      const o = { w: +s.kg > 0 ? +s.kg : null, r, type: { warmup: 'warmup', top: 'top', topset: 'top', backoff: 'backoff', amrap: 'amrap', drop: 'drop', dropset: 'drop' }[type] || 'working' };
      if (o.w) anyKg = true;
      if (s.rir != null && s.rir !== '' && !isNaN(+s.rir)) o.t = clamp(Math.round(+s.rir), 0, 10);
      if (+s.seconds > 0) o.sec = Math.round(+s.seconds);
      if (+s.metres > 0) o.m = +s.metres;
      return o;
    });
    if (range) notes.push(`${range[0]}–${range[1]} reps`);
    if (e.notes) notes.push(String(e.notes));
    const out = { name, notes: notes.join(' · '), sets };
    if (eq) out.equipment = eq;
    if (e.unilateral) out.execution = 'unilateral';
    if (sets.some(s => s.sec)) out.iso = true;
    return out;
  };
  const conv = d => ({ name: String(d.name || 'Day'), exercises: (d.exercises || []).map(ex) });
  const A = days.map(conv), Bd = B ? B.map(conv) : null;
  if (A.some(d => !d.exercises.length)) throw new Error('A day has no exercises.');
  const wdNum = Object.fromEntries(COACH_WD.map(w => [w[0], w[2]]));
  const P = { id, name: String(obj.name || 'Imported plan').slice(0, 60), ...(anyKg ? {} : { loads: 'rir' }), weekdays: wd.map(d => wdNum[d]), workouts: [] };
  for (let w = 1; w <= weeks; w++) (Bd && w % 2 === 0 ? Bd : A).forEach((d, di) => P.workouts.push({ week: w, day: di + 1, name: `${d.name}${Bd ? (w % 2 ? ' A' : ' B') : ''}`, block: `Week ${w}`, exercises: d.exercises }));
  return { P, warn, unknown: [...unknown], days: A, daysB: Bd, weeks, wd };
}
export function programName(id) {
  return PROGRAM_NAMES[id] || (S.programNames || {})[id] || (PROGRAM_MANIFEST && id === PROGRAM_MANIFEST.id ? PROGRAM_MANIFEST.name : null)
    || (S.coach && S.coach.plan && S.coach.planProg === id ? `Coach · ${S.coach.plan.name}` : null)
    || (String(id).startsWith('coach-') ? 'Coach plan' : String(id).startsWith('import-') ? 'Imported plan' : id);
}
/* Install, asking first about other programs that still have planned sessions. */
export function installAsking(P, startDate, replace, after) {
  const others = (S.programs || []).filter(id => !replace.includes(id) && S.workouts.some(w => w.prog === id && w.status === 'planned' && w.date >= today()));
  const go2 = dropOthers => {
    replace.filter(Boolean).forEach(removeProgram);
    if (dropOthers) others.forEach(removeProgram);
    S.programNames = { ...(S.programNames || {}), [P.id]: P.name };
    const n = installProgram(P, startDate);
    save(); bust();
    if (after) after(n);
  };
  if (!others.length) return go2(false);
  modal({
    title: 'Other planned sessions',
    body: `<p class="sub" style="margin-top:0">You also have <b>${esc(others.map(programName).join(', '))}</b> planned. Keep those sessions as well, or replace them with this plan? Anything already trained stays either way.</p>`,
    foot: `<button class="btn" id="coKeep">Keep both</button><button class="btn primary" id="coRepl">Replace them</button>`,
    onOpen: bg => { $('#coKeep', bg).onclick = () => { closeModal(); go2(false); }; $('#coRepl', bg).onclick = () => { closeModal(); go2(true); }; },
  });
}
export function openPlanImport(after, replace) {
  const st = aiStatus();
  modal({
    title: 'Bring in a plan',
    body: `<p class="sub" style="margin-top:0">Any plan works — from a coach, a spreadsheet, a PDF or your own notes. It needs turning into Ironlog's plan format first, and an AI does that well.</p>
      <div class="eyebrow">1 · With your own AI app</div>
      <div class="sub" style="margin:4px 0 6px">Copy the instructions, paste them into ChatGPT, Claude, Gemini or similar with your plan, then paste its reply below.</div>
      <button class="btn sm wide" id="piCopy">Copy instructions for your AI</button>
      <div class="eyebrow" style="margin-top:14px">2 · Or have Claude write it here</div>
      <div class="sub" style="margin:4px 0 6px">${st === 'on' ? 'Describe the plan or paste it in any format. Uses your AI key — about a penny or less.' : st === 'capped' ? 'Paused — this month\'s AI cap is reached (Settings → AI).' : 'Needs your own AI key (Settings → AI).'}</div>
      <textarea id="piDesc" rows="4" placeholder="e.g. 4 days upper/lower, 60 min, bench and deadlift focus — or paste the plan" ${st === 'on' ? '' : 'disabled'} style="width:100%"></textarea>
      <button class="btn sm wide" id="piAi" ${st === 'on' ? '' : 'disabled'} style="margin-top:6px">Write my plan</button>
      <div class="eyebrow" style="margin-top:14px">3 · Paste the plan, or load a file</div>
      <label class="sub" for="piText" style="display:block;margin:4px 0 6px">The JSON your AI wrote, or an Ironlog plan or program file.</label>
      <textarea id="piText" rows="5" placeholder='{ "format": "ironlog-plan", ... }' style="width:100%;font-family:ui-monospace,monospace;font-size:12px"></textarea>
      <div class="row" style="gap:8px;margin-top:6px"><button class="btn sm" id="piFile">Load a file</button><button class="btn sm primary grow" id="piGo">Check the plan</button></div>
      <div class="sub" id="piMsg" role="status" style="margin-top:8px"></div>`,
    foot: '<button class="btn ghost" data-close>Cancel</button>',
    onOpen: bg => {
      const msg = t => { $('#piMsg', bg).textContent = t; };
      $('#piCopy', bg).onclick = () => copyText(`${planFormatText()}\n\nMY PLAN\n(paste or describe your plan here)`, 'Instructions copied — paste them into your AI app');
      const check = text => {
        let res;
        try { res = planToProgram(planParse(text)); } catch (e) { return msg(e.message); }
        openPlanPreview(res, after, replace);
      };
      $('#piGo', bg).onclick = () => { const t = $('#piText', bg).value.trim(); if (!t) return msg('Paste the plan first, or load a file.'); check(t); };
      $('#piFile', bg).onclick = () => {
        const inp = document.createElement('input');
        inp.type = 'file'; inp.accept = '.json,.txt,application/json,text/plain';
        inp.onchange = async e => { const f = e.target.files[0]; if (!f) return; const t = await f.text(); $('#piText', bg).value = t; check(t); };
        inp.click();
      };
      $('#piAi', bg).onclick = async () => {
        const d = $('#piDesc', bg).value.trim();
        if (!d) return msg('Describe the plan or paste it in first.');
        const b = $('#piAi', bg); b.disabled = true; msg('Claude is writing your plan…');
        try {
          const r = await aiCall({ feature: 'plan', system: planFormatText(), user: d, maxTokens: 8000 });
          if (r.stop === 'max_tokens') throw new Error('The plan came back cut short — ask for fewer weeks or exercises.');
          $('#piText', bg).value = r.text; msg('');
          check(r.text);
        } catch (e) { msg(e.nokey || e.capped || e.net || e.status ? aiWhy(e) : e.message); }
        b.disabled = false;
      };
    },
  });
}
/* What will be installed, and anything that was guessed, before it is. */
function openPlanPreview(res, after, replace) {
  const P = res.P, sessions = P.workouts.length;
  const one = (x, s) => `${s.sec ? `${s.sec} s` : s.m ? `${s.m} m` : `${(x.notes.match(/^(\d+–\d+) reps/) || [])[1] || s.r || '?'} reps`}${s.t != null ? ` @ RIR ${s.t}` : ''}${s.w ? ` · ${wt(s.w)}` : ''}`;
  const fmtSet = x => {
    const same = x.sets.every(s => JSON.stringify(s) === JSON.stringify(x.sets[0]));
    return same ? `${x.sets.length} × ${one(x, x.sets[0] || {})}`
      : x.sets.map(s => `${one(x, s)}${s.type !== 'working' ? ` ${s.type === 'backoff' ? 'back-off' : s.type === 'warmup' ? 'warm-up' : s.type}` : ''}`).join(', ');
  };
  const rest = x => x.notes.replace(/^\d+–\d+ reps( · )?/, '');
  const dayCards = (list, label) => list.map(d => `<div class="co-day"><b>${esc(d.name)}${label ? ` · ${label}` : ''}</b>${d.exercises.map(x => `<div class="co-x"><div class="grow">${esc(x.name)}${x.equipment ? ` <span class="dimmer">(${esc(EQ_TITLE[x.equipment] || x.equipment)})</span>` : ''}
    <div class="sub">${esc(fmtSet(x))}${rest(x) ? ` · ${esc(rest(x))}` : ''}</div></div></div>`).join('')}</div>`).join('');
  modal({
    title: 'Check the plan',
    body: `<div style="font-weight:750;font-size:16px">${esc(P.name)}</div>
      <div class="sub" style="margin-bottom:8px">${res.days ? `${res.days.length} day${res.days.length === 1 ? '' : 's'} a week · ${res.weeks} weeks · ` : ''}${sessions} sessions${P.loads === 'rir' ? ' · weights from your history and RIR' : ''}</div>
      ${res.unknown.length ? `<div class="sub" style="color:var(--gold);margin-bottom:6px">Not in Ironlog's exercise list, so added as your own: ${esc(res.unknown.join(', '))}. They log fine, but have no muscle map or strength standard.</div>` : ''}
      ${res.warn.map(w => `<div class="sub" style="margin-bottom:4px">• ${esc(w)}</div>`).join('')}
      ${res.days ? dayCards(res.days, res.daysB ? 'A week' : '') + (res.daysB ? dayCards(res.daysB, 'B week') : '') : `<div class="sub">A full program file — ${sessions} sessions as written.</div>`}
      <div class="field" style="margin-top:12px"><label for="ppStart">Start</label><input type="date" id="ppStart" value="${today()}" min="${today()}"></div>`,
    foot: `<button class="btn ghost" data-close>Back</button><button class="btn primary" id="ppGo">Put it on my calendar</button>`,
    onOpen: bg => {
      $('#ppGo', bg).onclick = () => {
        const start = $('#ppStart', bg).value || today();
        installAsking(P, start, (replace || []).filter(Boolean), n => {
          closeAllModals(); render();
          toast(`${n} session${n === 1 ? '' : 's'} added from ${P.name}`, 'green');
          if (after) after(P, n);
        });
      };
    },
  });
}
